func (this *Tree) gtk_widget_get_preferred_size_(widget int64, requisition *gtk.GtkRequisition) {
	if this.columnCount == 0 {
		this.Composite.gtk_widget_get_preferred_size_(widget, requisition)
		return
	}
	var columns int64 = gtk.GTKGtk_tree_view_get_columns(this.Handle)
	var list int64 = columns
	var fixVisible bool = columns != 0
	for list != 0 {
		var column int64 = gtk.OSG_list_data(list)
		if gtk.GTKGtk_tree_view_column_get_visible(column) {
			fixVisible = false
			break
		}
		list = gtk.OSG_list_next(list)
	}
	var columnHandle int64 = int64(0)
	if fixVisible {
		columnHandle = gtk.OSG_list_data(columns)
		gtk.GTKGtk_tree_view_column_set_visible(columnHandle, true)
	}
	this.Composite.gtk_widget_get_preferred_size_(widget, requisition)
	if fixVisible {
		gtk.GTKGtk_tree_view_column_set_visible(columnHandle, false)
	}
	if columns != 0 {
		gtk.OSG_list_free(columns)
	}
}

