func (this *Tree) RecreateRenderers() {
	if this.checkRenderer != 0 {
		this.display.RemoveWidget(this.checkRenderer)
		gtk.OSG_object_unref(this.checkRenderer)
		if gtk.GTKGTK4 {
			this.checkRenderer = gtk.GTKGtk_cell_renderer_toggle_new()
		} else {
			if this.isOwnerDrawn {
				this.checkRenderer = gtk.OSG_object_new(this.display.Gtk_cell_renderer_toggle_get_type(), int64(0))
			} else {
				this.checkRenderer = gtk.GTKGtk_cell_renderer_toggle_new()
			}
		}
		if this.checkRenderer == 0 {
			this.Error(ERROR_NO_HANDLES)
		}
		gtk.OSG_object_ref(this.checkRenderer)
		this.display.AddWidget(this.checkRenderer, upcastTreeToWidget(this))
		gtk.OSG_signal_connect_closure(this.checkRenderer, gtk.OSToggled, this.display.GetClosure(WidgetTOGGLED), false)
	}
	if this.columnCount == 0 {
		this.CreateRenderers(gtk.GTKGtk_tree_view_get_column(this.Handle, 0), TreeFIRST_COLUMN, true, 0)
	} else {
		for i := int32(0); i < this.columnCount; i++ {
			var column *TreeColumn = this.columns[i]
			this.CreateRenderers(column.Handle, column.modelIndex, i == 0, column.style)
		}
	}
}

