		var g_class int64 = gtk.OSG_type_class_peek_parent(gtk.OSG_OBJECT_GET_CLASS(cell))
		var klass gtk.GtkCellRendererClass = gtk.GtkCellRendererClass{}
		gtk.OSMemmoveOverload12(&klass, g_class)
